module painting2x2 (\n    input clk, rst_n, start,\n    input [3:0] target,\n    output reg [3:0] painted,\n    output reg [2:0] min_diff,\n    output reg done\n);\n    // State declarations\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH  = 2'd2;\n    \n    reg [1:0] state;\n    reg [1:0] white_idx, black_idx;\n    reg [5:0] pair_counter;  // Up to 40 pairs (6-bit)\n    reg [2:0] current_cost, stored_min;\n    reg [1:0] best_white, best_black;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            painted <= 4'b0;\n            min_diff <= 3'b0;\n            stored_min <= 3'd4;  // Max possible cost\n            white_idx <= 2'b0;\n            black_idx <= 2'b0;\n            pair_counter <= 6'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    stored_min <= 3'd4;  // Reset min cost\n                    pair_counter <= 6'd0;\n                    if (start) begin\n                        state <= COMPUTE;\n                        white_idx <= 2'd0;\n                        black_idx <= 2'd1;  // Start at first valid pair (0,1)\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (pair_counter < 6'd12) begin\n                        // Calculate current cost (0-2 possible)\n                        current_cost <= (target[white_idx] ? 2'd1 : 2'd0) + (target[black_idx] ? 2'd0 : 2'd1);\n                        \n                        // Update best combination\n                        if (current_cost < stored_min) begin\n                            stored_min <= current_cost;\n                            best_white <= white_idx;\n                            best_black <= black_idx;\n                        end\n                        \n                        // Advance to next pair\n                        pair_counter <= pair_counter + 6'd1;\n                        if (black_idx == 2'd3) begin\n                            white_idx <= white_idx + 2'd1;\n                            black_idx <= (white_idx + 2'd2);\n                        end else begin\n                            black_idx <= black_idx + 2'd1;\n                        end\n                    end else begin\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    // Apply best painting\n                    painted <= target;\n                    painted[best_white] <= 1'b0;\n                    painted[best_black] <= 1'b1;\n                    min_diff <= stored_min;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule